      "openapi": "3.1.0",
      "info": {
        "title": "Meridian Transit Cloud \u2014 a SaaS API for regional public-transit agencies to publish real-time vehicle positions, trip updates, and rider-facing alerts. API",
        "version": "1.0.0",
        "description": "Meridian Transit API: a multi-tenant REST service exposing GTFS-Realtime-derived feeds (vehicle positions, trip delays, service alerts) plus an authoring surface for agency operators to push alerts. Auth is OAuth2 client_credentials with short-lived bearer tokens scoped per agency."
      },
